using System.Collections;
using UnityEngine;
namespace CoopBeam {
public class FireForgeBoss:MonoBehaviour {
 public Collider2D core;public SpriteRenderer coreArt;public int Phase{get;private set;}=1;public int PatternIndex{get;private set;}public bool Vulnerable{get;private set;}public bool Telegraphing{get;private set;}public bool Attacking{get;private set;}public bool Defeated{get;private set;}public float DefeatAge=>Defeated?Time.time-defeatedAt:0;public int PatternsCompleted{get;private set;}public int Transformations{get;private set;}public string Hint{get;private set;}="LA GRAN FORJA DESPIERTA";
 EnemyBase enemy;int sequence,target;float defeatedAt;bool transforming;
 void Awake(){enemy=GetComponent<EnemyBase>();enemy.externalControl=true;}
 IEnumerator Start(){core.enabled=false;yield return new WaitUntil(()=>GameManager.Instance&&GameManager.Instance.Running);while(!Defeated){int desired=enemy.Health<=enemy.maxHealth*.35f+.01f?3:enemy.Health<=enemy.maxHealth*.7f+.01f?2:1;if(desired>Phase){yield return Transform(desired);continue;}yield return Pattern();}}
 public float FilterDamage(float amount,float health){if(!Vulnerable||Defeated||transforming)return 0;float floor=Phase==1?enemy.maxHealth*.7f:Phase==2?enemy.maxHealth*.35f:0;return Mathf.Min(amount,Mathf.Max(0,health-floor));}
 IEnumerator Transform(int phase){transforming=true;Vulnerable=Telegraphing=Attacking=false;core.enabled=false;EncounterHazard.ClearOwned(this);Hint=phase==2?"LOS FUELLES RUGEN / BUSQUEN LAS ALTURAS":"LA FORJA SE ABRE / ULTIMA FUNDICION";for(int i=0;i<12;i++){FireFX.Burst(transform.position+(Vector3)Random.insideUnitCircle,Color.yellow,8);yield return new WaitForSeconds(.2f);if(!GameManager.Instance.Running)yield break;}Phase=phase;Transformations++;sequence=0;transforming=false;}
 IEnumerator Pattern(){var game=GameManager.Instance;if(!game.Running)yield break;Vulnerable=false;core.enabled=false;PatternIndex=sequence++%5;target=1-target;if(game.players[target].Dead)target=1-target;Vector2 aim=game.players[target].transform.position;Vector2 launch=(Vector2)transform.position+Vector2.up*1.3f;Telegraphing=true;enemy.combatTelegraph=true;
  Hint=PatternIndex==0?"MARTILLOS / SALGAN DE LAS MARCAS CIAN":PatternIndex==1?"RUEDA SOLAR / BUSQUEN LOS HUECOS":PatternIndex==2?"RIO PARTIDO / SUBAN A LOS REFUGIOS":PatternIndex==3?"COMETAS / NO SE QUEDEN EN EL IMPACTO":"ALIENTO DE FORJA / CAMBIEN DE ALTURA";
  if(PatternIndex==0)for(int i=0;i<Phase+1;i++){float x=Mathf.Clamp(aim.x+(i-(Phase*.5f))*3,-9.5f,9.5f);FireHazard.Spawn(new Vector2(x,-2.7f),new Vector2(1.1f,3),1.25f,.9f,Vector2.zero,this,1,false);}
  if(PatternIndex==2)for(int i=-9;i<=9;i+=3){if(Mathf.Abs(i-(target==0?-6:6))<1)continue;FireHazard.Spawn(new Vector2(i,-4.03f),new Vector2(2.1f,.5f),1.3f,1.4f,Vector2.zero,this,1,false);}
  yield return new WaitForSeconds(1.2f);if(!game.Running||Defeated)yield break;Telegraphing=enemy.combatTelegraph=false;Attacking=true;FireFX.Burst(launch,new Color(1,.8f,.2f),16);game.Tone(170+Phase*35,.14f);
  if(PatternIndex==1){int count=Phase==1?8:10;for(int i=0;i<count;i++){if(i==1||i==count/2+1)continue;float angle=(i*360f/count+20)*Mathf.Deg2Rad;Vector2 d=new Vector2(Mathf.Cos(angle),Mathf.Sin(angle));FireHazard.Spawn(launch+d*.65f,Vector2.one*.5f,.06f,2.6f,d*(3.1f+Phase*.2f),this);}}
  if(PatternIndex==3){for(int i=0;i<Phase+2;i++){float x=Mathf.Clamp(aim.x+(i-(Phase+1)*.5f)*2.2f,-9,9);FireHazard.Spawn(launch,Vector2.one*.65f,.1f,3,new Vector2((x-launch.x)/1.5f,7+i*.35f),this,0,true,9);FireHazard.Spawn(new Vector2(x,-3.9f),new Vector2(1.2f,.65f),1.7f,.7f,Vector2.zero,this,1,false);}}
  if(PatternIndex==4){Vector2 d=(aim-launch).normalized;for(int i=-Phase-1;i<=Phase+1;i++){Vector2 v=Quaternion.Euler(0,0,i*15)*d;FireHazard.Spawn(launch+v*.8f,new Vector2(.55f,.75f),.1f,2.3f,v*4.5f,this,1);}}
  yield return new WaitForSeconds(PatternIndex==3?3:2.5f);if(!game.Running||Defeated)yield break;Attacking=false;EncounterHazard.ClearOwned(this);Vulnerable=true;core.enabled=true;core.transform.localPosition=new Vector3(0,Phase==2?1.1f:.2f,0);coreArt.transform.localPosition=core.transform.localPosition;Hint=Phase==2?"CORAZON ALTO / CRUCEN UN LAZO DIAGONAL":"FUELLE ABIERTO / ENLACEN EL CORAZON";yield return new WaitForSeconds(Phase==3?3.6f:3.1f);Vulnerable=false;core.enabled=false;PatternsCompleted++;
 }
 void Update(){if(coreArt){coreArt.color=Vulnerable?new Color(1,.85f,.3f):new Color(1,.25f,.08f,.25f);coreArt.transform.localScale=Vector3.one*(Vulnerable?1.1f+Mathf.Sin(Time.time*9)*.12f:.65f);}if(GameManager.Instance&&!GameManager.Instance.Running&&!Defeated){StopAllCoroutines();Vulnerable=false;core.enabled=false;EncounterHazard.ClearOwned(this);}}
 public void Defeat(){if(Defeated)return;Defeated=true;defeatedAt=Time.time;StopAllCoroutines();Vulnerable=Telegraphing=Attacking=false;foreach(var c in GetComponentsInChildren<Collider2D>())c.enabled=false;EncounterHazard.ClearOwned(this);StartCoroutine(Fall());}
 IEnumerator Fall(){Hint="LA FORJA DESCANSA / REINO LIBERADO";for(int i=0;i<12;i++){FireFX.Burst(transform.position+(Vector3)Random.insideUnitCircle*1.5f,i%2==0?Color.yellow:new Color(1,.3f,.05f),10);yield return new WaitForSeconds(.16f);}enemy.FinishDeath();}
 void OnDisable(){EncounterHazard.ClearOwned(this);}
 void OnGUI(){if(!GameManager.Instance||!GameManager.Instance.Running)return;GUI.depth=-1;PixelFont.Begin();Color gold=new Color(1,.7f,.15f);PixelFont.Panel(new Rect(110,77,420,38),PixelFont.Ink,gold);PixelFont.Fill(new Rect(120,85,400,5),new Color(.25f,.1f,.15f));PixelFont.Fill(new Rect(120,85,400*Mathf.Clamp01(enemy.Health/enemy.maxHealth),5),gold);PixelFont.Text(320,94,"BRONTOFORNO / FASE "+Phase,1,PixelFont.Cream,true);PixelFont.Text(320,105,Hint,1,Color.cyan,true);}
}
}
